<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import DefaultLayout from '@/layouts/DefaultLayout.vue';import BaseButton from '@/components/ui/BaseButton.vue';import{useApi}from'@/composables/useApi';import type{ApiResponse,Order}from'@/types';const route=useRoute(),api=useApi(),order=ref<Order|null>(null),error=ref('');const money=(n:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(n);async function load(){const r=await api.get<ApiResponse<Order>>(`/orders/${route.params.orderId}`);order.value=r.data||null}async function pay(){try{const r=await api.post<ApiResponse<{mockPaymentUrl:string}>>(`/orders/${route.params.orderId}/payments/mock`);if(r.data?.mockPaymentUrl)window.open(r.data.mockPaymentUrl,'_blank')}catch(e){error.value=e instanceof Error?e.message:'Không tạo được thanh toán'}}onMounted(load)</script>
<template><DefaultLayout><main class="mx-auto max-w-2xl px-4 py-12"><div v-if="order" class="rounded-3xl border bg-white p-7 dark:border-slate-800 dark:bg-slate-900"><h1 class="text-3xl font-extrabold">Thanh toán</h1><p class="mt-1 text-slate-500">Đơn {{ order.orderNumber }}</p><div v-for="i in order.items" :key="i.id" class="my-6 flex justify-between border-y py-5"><span>{{ i.courseTitleSnapshot }}</span><b>{{ money(i.priceSnapshot) }}</b></div><div class="flex justify-between text-xl"><b>Tổng cộng</b><b class="text-purple-600">{{ money(order.total) }}</b></div><p v-if="error" class="mt-4 text-red-600">{{ error }}</p><BaseButton class="mt-7 w-full" @click="pay">Mở cổng thanh toán mock</BaseButton><p class="mt-3 text-center text-xs text-slate-500">Thanh toán mở ở tab mới. Hoàn tất xong hãy quay lại trang kết quả.</p><RouterLink :to="`/payment-result/${order.id}`" class="mt-4 block text-center font-semibold text-purple-600">Kiểm tra kết quả thanh toán →</RouterLink></div></main></DefaultLayout></template>
